    if len(cs)>=2:
        for c in range(min(cs),max(cs)+1):
            if out[r][c]==9: out[r][c]=3
for c in range(len(grid[0])):
    rs=[r for r in range(len(grid)) if grid[r][c]==6]
    if len(rs)>=2:
        for r in range(min(rs),max(rs)+1):
            if out[r][c]==9: out[r][c]=3
